        "对战",
        "在标准对战模式的时候使用近战AI。|n|n对战模式的AI会更有效的和盟友一起进攻和防守。",
        "保护使用者",
        "当这个选项被启动的时候，AI会试图保护那些遭受攻击的使用者控制单位。",
        "随机路径",
        "使用此项功能后，AI会在随机方式中倾向于选择目的地.",
