        "在这个选项设置有效的情况下，可以让工人自动修理需要修理建筑。",
        "英雄逃跑",
        "栽照父蜒舷缮种佑行档乔靠舷,热构佑行栽照抖种蜒种适缮换照挝贩照抖适＃怂换适鬃创照吵种烫排　 ",
        "单位逃跑",
        "在这个选项设置有效的情况下，非英雄的部队在无法攻击或是受到重伤的时候，会试着逃离战场。",
        "组队逃跑",
        "在这个选项设置有效的情况下，如果他们一面倒或是极为不利，攻击群会试着从战场中逃跑。",
        "没有仁慈",
        "在这个选项设置有效的情况下，AI会在敌人较弱或是占到优势的时候，进行攻击。|n|n注意到这些攻击相当于'敌人 - 主攻'的目标类型。",
        "受伤忽略",
        "在这个选项设置有效的情况下，在集结进攻力量的时候，忽略生命值低于50%的单位。",
        "去除受伤者",
        "在这个选项设置有效的情况下，会周期性的把受伤的单位送回家（或者送到生命之泉）回复生命。",
        "拾取物品",
        "在这个选项设置有效的情况下，英雄可以试着拾取任何路上找到的有用物品。",
